#!/usr/bin/env python3
"""
lora_workflow_renamer_z.py — LoRA Workflow Renamer Z (merged single-file, GUI edition)

Scans a folder of ComfyUI workflow JSON files, finds any LoraLoader nodes
inside each one, and renames the file to a comma-separated list of the
LoRAs it uses.

This is a GUI-only application (Tkinter). Run it with no arguments to
open the window:

    python lora_workflow_renamer_z.py

A small CLI fallback is also available for scripting/automation:

    python lora_workflow_renamer_z.py --folder /path/to/workflows
"""

import os
import re
import sys
import json
import argparse
import threading
import platform
import configparser
import tkinter as tk
from tkinter import ttk, filedialog, messagebox

# ─────────────────────────────────────────────────────────────────────────────
#  Built-in application icon
#  The icon is embedded directly so no external asset file is required,
#  both when running from source and inside a frozen PyInstaller executable.
#
#  _ICON_SVG        — vector source; written to ~/.local/share/icons on Linux
#  _ICON_ICO_B64    — multi-resolution Windows .ico (BMP-encoded, NOT PNG-
#                     compressed) so PyInstaller can attach it to the .exe.
#                     PyInstaller's Windows icon-embedding step copies the
#                     raw bytes of each ICO entry straight into the .exe's
#                     RT_ICON resource with no validation or conversion, and
#                     that resource format requires classic BMP/DIB data —
#                     PNG-compressed entries (Pillow's default for large
#                     sizes) silently produce an .exe with a broken/invisible
#                     icon. bitmap_format="bmp" avoids this.
#  _ICON_PNG64_B64  — 64×64 PNG for the live Tk window / taskbar icon
# ─────────────────────────────────────────────────────────────────────────────
