def _apply_window_icon(root):
    """Set the Tk window / taskbar icon from the embedded PNG64."""
    try:
        data = _base64.b64decode(_ICON_PNG64_B64)
        img = tk.PhotoImage(data=_base64.b64encode(data))
        root.tk.call("wm", "iconphoto", root._w, img)
        root._icon_ref = img  # keep a reference alive (Tk needs this)
    except Exception:
        pass


def _extract_icons(out_dir: str) -> None:
    """
    Write embedded icon assets to *out_dir* as standalone files:
      lora_workflow_renamer_z.svg  — vector (Linux .desktop / sidebar icon)
      lora_workflow_renamer_z.ico  — multi-res BMP .ico (embedded into .exe)
      lora_workflow_renamer_z.png  — 64×64 PNG (Tk taskbar icon / Linux fallback)
    Called by build.sh / build.bat before PyInstaller compiles the executable.
    """
    out = _pathlib.Path(out_dir)
    out.mkdir(parents=True, exist_ok=True)
    (out / "lora_workflow_renamer_z.svg").write_text(_ICON_SVG, encoding="utf-8")
    (out / "lora_workflow_renamer_z.ico").write_bytes(_base64.b64decode(_ICON_ICO_B64))
    (out / "lora_workflow_renamer_z.png").write_bytes(_base64.b64decode(_ICON_PNG64_B64))
    print(f"Icons extracted to: {out}")

# ─────────────────────────────────────────────────────────────────────────────
#  Core logic — shared between the GUI and the CLI fallback
# ─────────────────────────────────────────────────────────────────────────────

def clean_filename(filename):
    # Remove invalid characters and replace with underscores
    return re.sub(r'[<>:"/\\|?*]', '_', filename)


def get_loras_from_json(json_data):
    loras = set()  # Using a set to avoid duplicates

    def search_loras(data):
        if isinstance(data, dict):
            # Check if this is a LoraLoader node
            if data.get('type') == 'LoraLoader':
                # Get LORA name from widgets_values
                widgets_values = data.get('widgets_values', [])
                if widgets_values and isinstance(widgets_values[0], str):
                    lora_name = widgets_values[0]
                    if lora_name.endswith('.safetensors'):
                        loras.add(lora_name.replace('.safetensors', ''))
                    else:
                        loras.add(lora_name)

            # Search in nested structures
            for value in data.values():
                search_loras(value)
        elif isinstance(data, list):
            # Search in all list items
            for item in data:
                search_loras(item)

    try:
        search_loras(json_data)
    except Exception as e:
        print(f"Error while searching for LORAs: {e}")

    return sorted(list(loras))  # Convert set back to sorted list


def resolve_new_name(folder_path, filename, loras):
    """Compute the de-duplicated target filename for a rename, without
    performing the rename. Shared by the GUI and the CLI fallback."""
    new_name = ','.join(loras)
    if len(new_name) > 200:  # Limit filename length
        new_name = new_name[:197] + '...'
    new_name = clean_filename(new_name) + '.json'
    new_path = os.path.join(folder_path, new_name)

    counter = 1
    base_new_name = new_name[:-5]  # Remove .json
    file_path = os.path.join(folder_path, filename)
    while os.path.exists(new_path) and new_path != file_path:
        new_name = f"{base_new_name}_{counter}.json"
        new_path = os.path.join(folder_path, new_name)
        counter += 1
    return new_name, new_path


# ─────────────────────────────────────────────────────────────────────────────
#  Config persistence — saves/loads the last-used folder per OS
# ─────────────────────────────────────────────────────────────────────────────

def _config_path() -> str:
    """Return the platform-appropriate .ini path."""
    if platform.system() == "Windows":
        base = os.environ.get("APPDATA", os.path.expanduser("~"))
        return os.path.join(base, "LoRA_Workflow_Renamer_Z", "loras_config_windows.ini")
    else:
        return os.path.join(
            os.environ.get("XDG_CONFIG_HOME", os.path.join(os.path.expanduser("~"), ".config")),
            "LoRA_Workflow_Renamer_Z",
            "loras_config_linux.ini",
        )


def _load_saved_folder() -> str:
    """Return the last saved folder, or '' if none."""
    path = _config_path()
    if not os.path.isfile(path):
        return ""
    cfg = configparser.ConfigParser()
    try:
        cfg.read(path, encoding="utf-8")
        return cfg.get("Settings", "last_folder", fallback="")
    except Exception:
        return ""


def _save_folder(folder: str) -> None:
    """Persist *folder* to the platform config file."""
    path = _config_path()
    os.makedirs(os.path.dirname(path), exist_ok=True)
    cfg = configparser.ConfigParser()
    cfg["Settings"] = {"last_folder": folder}
    try:
        with open(path, "w", encoding="utf-8") as fh:
            cfg.write(fh)
    except Exception:
        pass


def _load_backup_config() -> dict:
    """Return persisted backup settings as {'backup_enabled': bool, 'backup_folder': str}."""
    path = _config_path()
    if not os.path.isfile(path):
        return {}
    cfg = configparser.ConfigParser()
    try:
        cfg.read(path, encoding="utf-8")
        return {
            "backup_enabled": cfg.getboolean("Backup", "enabled", fallback=False),
            "backup_folder":  cfg.get("Backup", "folder", fallback=""),
        }
    except Exception:
        return {}


def _save_backup_config(data: dict) -> None:
    """Persist backup settings into the [Backup] section of the config file."""
    path = _config_path()
    os.makedirs(os.path.dirname(path), exist_ok=True)
    cfg = configparser.ConfigParser()
    if os.path.isfile(path):
        try:
            cfg.read(path, encoding="utf-8")
        except Exception:
            pass
    if "Backup" not in cfg:
        cfg["Backup"] = {}
    if "enabled" in data or "backup_enabled" in data:
        cfg["Backup"]["enabled"] = str(bool(data.get("backup_enabled", data.get("enabled", False))))
    if "backup_folder" in data:
        cfg["Backup"]["folder"] = data["backup_folder"]
    try:
        with open(path, "w", encoding="utf-8") as fh:
            cfg.write(fh)
    except Exception:
        pass


