# ─────────────────────────────────────────────────────────────────────────────
#  Linux — modern tree-based folder picker using Zenity / kdialog / yad
#  Falls back to Tkinter's native askdirectory if none of those are present.
# ─────────────────────────────────────────────────────────────────────────────

def _linux_folder_picker(initial_dir: str = "") -> str:
    """
    Open a tree-based folder-selection dialog on Linux using the best
    available tool (zenity → kdialog → yad → Tkinter fallback).

    Returns the chosen path as a string, or '' if the user cancelled.
    """
    import shutil, subprocess

    start = initial_dir if initial_dir and os.path.isdir(initial_dir) else os.path.expanduser("~")

    # ── zenity (GNOME / Dolphin-style GTK file-chooser) ──────────────────
    if shutil.which("zenity"):
        try:
            result = subprocess.run(
                ["zenity", "--file-selection", "--directory",
                 "--title=Select Folder",
                 f"--filename={start}/"],
                capture_output=True, text=True, timeout=120,
            )
            if result.returncode == 0:
                return result.stdout.strip()
            return ""
        except Exception:
            pass

    # ── kdialog (KDE / Dolphin-native) ───────────────────────────────────
    if shutil.which("kdialog"):
        try:
            result = subprocess.run(
                ["kdialog", "--getexistingdirectory", start,
                 "--title", "Select Folder"],
                capture_output=True, text=True, timeout=120,
            )
            if result.returncode == 0:
                return result.stdout.strip()
            return ""
        except Exception:
            pass

    # ── yad (Yet Another Dialog — tree-capable GTK) ───────────────────────
    if shutil.which("yad"):
        try:
            result = subprocess.run(
                ["yad", "--file", "--directory",
                 f"--filename={start}/",
                 "--title=Select Folder"],
                capture_output=True, text=True, timeout=120,
            )
            if result.returncode == 0:
                return result.stdout.strip()
            return ""
        except Exception:
            pass

    # ── Tkinter fallback ─────────────────────────────────────────────────
    chosen = filedialog.askdirectory(initialdir=start if start else None)
    return chosen or ""


def _pick_folder(initial_dir: str = "") -> str:
    """Cross-platform folder picker wrapper."""
    if platform.system() == "Linux":
        return _linux_folder_picker(initial_dir)
    # Windows / macOS — use Tkinter's native dialog
    start = initial_dir if initial_dir and os.path.isdir(initial_dir) else None
    chosen = filedialog.askdirectory(initialdir=start)
    return chosen or ""


# ─────────────────────────────────────────────────────────────────────────────
#  GUI — Tkinter frontend
# ─────────────────────────────────────────────────────────────────────────────

class WorkflowRenamerGUI:
    def __init__(self, root):
        self.root = root
        _apply_window_icon(self.root)

        # Language state — "en" or "pt"
        self._lang = "en"

        # Load last saved folder (empty string = no default)
        saved = _load_saved_folder()
        self.folder_path = tk.StringVar(value=saved)

        self.root.geometry("800x640")

        # ── Main frame ────────────────────────────────────────────────────
        self.main_frame = ttk.Frame(root, padding="10")
        self.main_frame.grid(row=0, column=0, sticky=(tk.W, tk.E, tk.N, tk.S))

        # ── Row 0: workflow folder entry + Browse + Process + Lang ────────
        self.folder_frame = ttk.Frame(self.main_frame)
        self.folder_frame.grid(row=0, column=0, columnspan=2, sticky=(tk.W, tk.E), pady=5)

        self.folder_entry = ttk.Entry(self.folder_frame, textvariable=self.folder_path, width=55)
        self.folder_entry.grid(row=0, column=0, padx=(5, 3), sticky=(tk.W, tk.E))
        self.folder_frame.columnconfigure(0, weight=1)

        self.button_frame = ttk.Frame(self.folder_frame)
        self.button_frame.grid(row=0, column=1, padx=(3, 5))

        self.browse_button = ttk.Button(
            self.button_frame, text=self._s("browse"), command=self.browse_folder
        )
        self.browse_button.pack(side=tk.LEFT, padx=2)

        self.process_button = ttk.Button(
            self.button_frame, text=self._s("process"), command=self.start_processing
        )
        self.process_button.pack(side=tk.LEFT, padx=2)

        # Language toggle button — rightmost in the button frame
        self.lang_button = ttk.Button(
            self.button_frame, text=self._s("lang_toggle"), width=6,
            command=self.toggle_language
        )
        self.lang_button.pack(side=tk.LEFT, padx=(6, 2))

        # ── Row 1: backup controls ────────────────────────────────────────
        backup_outer = ttk.Frame(self.main_frame)
        backup_outer.grid(row=1, column=0, columnspan=2, sticky=(tk.W, tk.E), pady=(2, 4))

        # Checkbox
        self.backup_enabled_var = tk.BooleanVar(value=False)
        self.backup_chk = ttk.Checkbutton(
            backup_outer,
            text=self._s("chk_backup"),
            variable=self.backup_enabled_var,
            command=self._on_backup_toggle,
        )
        self.backup_chk.pack(side=tk.LEFT, padx=(5, 8))

        # Label
        self.backup_lbl = ttk.Label(backup_outer, text=self._s("lbl_backup"))
        self.backup_lbl.pack(side=tk.LEFT)

        # Entry
        self.backup_var = tk.StringVar(value="")
        self.backup_entry = ttk.Entry(backup_outer, textvariable=self.backup_var, width=38)
        self.backup_entry.pack(side=tk.LEFT, padx=(4, 3), fill=tk.X, expand=True)
        self.backup_entry.configure(state="disabled")

        # Browse button for backup
        self.backup_browse_btn = ttk.Button(
            backup_outer, text=self._s("browse_backup"),
            command=self._browse_backup_folder,
        )
        self.backup_browse_btn.pack(side=tk.LEFT, padx=(0, 5))
        self.backup_browse_btn.configure(state="disabled")

        # Restore persisted backup settings from config
        cfg_bk = _load_backup_config()
        if cfg_bk.get("backup_folder"):
            self.backup_var.set(cfg_bk["backup_folder"])
        if cfg_bk.get("backup_enabled", False):
            self.backup_enabled_var.set(True)
            self._on_backup_toggle()

        # ── Row 2: progress bar ───────────────────────────────────────────
        self.progress_var = tk.DoubleVar()
        self.progress_bar = ttk.Progressbar(
            self.main_frame, variable=self.progress_var, maximum=100
        )
        self.progress_bar.grid(row=2, column=0, columnspan=2, sticky=(tk.W, tk.E), pady=5)

        # ── Row 3: output text area ───────────────────────────────────────
        self.output_frame = ttk.Frame(self.main_frame)
        self.output_frame.grid(row=3, column=0, columnspan=2,
                               sticky=(tk.W, tk.E, tk.N, tk.S), pady=5)

        self.output_text = tk.Text(self.output_frame, height=20, width=80, wrap=tk.WORD)
        self.output_text.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        self.scrollbar = ttk.Scrollbar(
            self.output_frame, orient=tk.VERTICAL, command=self.output_text.yview
        )
        self.scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        self.output_text["yscrollcommand"] = self.scrollbar.set

        # ── Grid weights ─────────────────────────────────────────────────
        self.root.columnconfigure(0, weight=1)
        self.root.rowconfigure(0, weight=1)
        self.main_frame.columnconfigure(1, weight=1)
        self.main_frame.rowconfigure(3, weight=1)

        # Processing flag
        self.is_processing = False

        # Apply initial title and labels
        self._apply_language()

    # ── i18n helpers ──────────────────────────────────────────────────────

    def _s(self, key: str, *args) -> str:
        """Return the localised string for *key*, formatted with *args*."""
        template = _STRINGS[self._lang].get(key, key)
        return template.format(*args) if args else template

    def _apply_language(self) -> None:
        """Re-label every widget with the current language strings."""
        self.root.title(self._s("title"))
        self.browse_button.configure(text=self._s("browse"))
        if self.is_processing:
            self.process_button.configure(text=self._s("cancel"))
        else:
            self.process_button.configure(text=self._s("process"))
        self.lang_button.configure(text=self._s("lang_toggle"))
        self.backup_chk.configure(text=self._s("chk_backup"))
        self.backup_lbl.configure(text=self._s("lbl_backup"))
        self.backup_browse_btn.configure(text=self._s("browse_backup"))
        if not self.folder_path.get():
            self.folder_entry.configure(foreground="grey")

    def toggle_language(self) -> None:
        self._lang = "pt" if self._lang == "en" else "en"
        self._apply_language()

    # ── Backup helpers ────────────────────────────────────────────────────

    def _on_backup_toggle(self) -> None:
        """Enable/disable backup folder controls and persist the choice."""
        enabled = self.backup_enabled_var.get()
        state = "normal" if enabled else "disabled"
        self.backup_entry.configure(state=state)
        self.backup_browse_btn.configure(state=state)
        _save_backup_config({"backup_enabled": enabled,
                              "backup_folder": self.backup_var.get().strip()})

    def _browse_backup_folder(self) -> None:
        current = self.backup_var.get().strip()
        initial = current if current and os.path.isdir(current) else ""
        chosen = _pick_folder(initial)
        if chosen:
            self.backup_var.set(chosen)
            _save_backup_config({"backup_enabled": self.backup_enabled_var.get(),
                                  "backup_folder": chosen})

    def _backup_enabled(self) -> bool:
        return self.backup_enabled_var.get()

    def _get_backup_folder(self) -> str:
        """Return the backup folder path string, or '' if backup is off."""
        if not self._backup_enabled():
            return ""
        return self.backup_var.get().strip()

    def _ensure_backup_folder(self, path: str) -> bool:
        """Create the backup folder if needed. Returns False on failure."""
        try:
            os.makedirs(path, exist_ok=True)
            return True
        except Exception as exc:
            messagebox.showerror(
                self._s("err_backup_t"),
                self._s("err_backup_m", exc),
            )
            return False

    def _do_backup(self, file_path: str, backup_folder: str) -> str:
        """Copy file_path into backup_folder and return the backup path."""
        import shutil as _shutil
        dest = os.path.join(backup_folder, os.path.basename(file_path))
        _shutil.copy2(file_path, dest)
        return dest

    # ── Folder browsing ───────────────────────────────────────────────────

    def browse_folder(self) -> None:
        current = self.folder_path.get()
        initial = current if current and os.path.isdir(current) else ""
        chosen = _pick_folder(initial)
        if chosen:
            self.folder_path.set(chosen)
            _save_folder(chosen)

    # ── Output helpers ────────────────────────────────────────────────────

    def update_output(self, text: str) -> None:
        self.output_text.insert(tk.END, text + "\n")
        self.output_text.see(tk.END)
        self.root.update_idletasks()

    # ── Core processing ───────────────────────────────────────────────────

    def process_files(self) -> None:
        folder_path = self.folder_path.get().strip()

        if not folder_path:
            messagebox.showerror(self._s("err_title"), self._s("err_no_folder"))
            self.is_processing = False
            self.process_button.configure(text=self._s("process"))
            return

        if not os.path.exists(folder_path):
            messagebox.showerror(self._s("err_title"), self._s("err_not_exist"))
            self.is_processing = False
            self.process_button.configure(text=self._s("process"))
            return

        # Validate backup settings before starting
        backup_folder = self._get_backup_folder()
        if self._backup_enabled() and not backup_folder:
            messagebox.showwarning(self._s("warn_no_backup_t"), self._s("warn_no_backup_m"))
            self.is_processing = False
            self.process_button.configure(text=self._s("process"))
            return
        if backup_folder and not self._ensure_backup_folder(backup_folder):
            self.is_processing = False
            self.process_button.configure(text=self._s("process"))
            return

        # Persist the workflow folder
        _save_folder(folder_path)

        self.update_output(self._s("processing_in", folder_path))

        ignore_files = [
            "video_wan2_2_5b_i2v",
            "depth_controlnet",
            "flux_redux_model_example",
            "image_qwen_image_union_control_lora",
            "image2image",
        ]

        json_files = [f for f in os.listdir(folder_path) if f.endswith(".json")]
        total_files = len(json_files)
        processed_files = 0

        for filename in json_files:
            if not self.is_processing:
                break

            base_name = os.path.splitext(filename)[0]
            if any(ignore in base_name.lower() for ignore in ignore_files):
                self.update_output(self._s("skip_ignored", filename))
                processed_files += 1
                self.progress_var.set((processed_files / total_files) * 100)
                continue

            file_path = os.path.join(folder_path, filename)
            self.update_output(self._s("proc_file", filename))

            try:
                with open(file_path, "r", encoding="utf-8") as fh:
                    try:
                        json_data = json.load(fh)
                        self.update_output(self._s("loaded_ok", filename))
                    except json.JSONDecodeError as exc:
                        self.update_output(self._s("json_err", filename, exc))
                        continue

                loras = get_loras_from_json(json_data)

                if not loras:
                    self.update_output(self._s("no_loras", filename))
                    processed_files += 1
                    self.progress_var.set((processed_files / total_files) * 100)
                    continue

                self.update_output(self._s("found_loras", filename, ", ".join(loras)))

                new_name, new_path = resolve_new_name(folder_path, filename, loras)

                if new_path != file_path:
                    # Backup before rename (backup folder already validated above)
                    if backup_folder:
                        bk = self._do_backup(file_path, backup_folder)
                        self.update_output(self._s("backup_created", bk))
                    else:
                        self.update_output(self._s("backup_disabled"))
                    try:
                        os.rename(file_path, new_path)
                        self.update_output(self._s("renamed", filename, new_name))
                    except OSError as exc:
                        self.update_output(self._s("rename_err", filename, exc))
                else:
                    self.update_output(self._s("already_named", filename))

            except Exception as exc:
                self.update_output(self._s("unexpected_err", filename, exc))

            processed_files += 1
            self.progress_var.set((processed_files / total_files) * 100)

        if self.is_processing:
            self.update_output(self._s("done"))
        else:
            self.update_output(self._s("cancelled"))

        self.is_processing = False
        self.process_button.configure(text=self._s("process"))

    def start_processing(self) -> None:
        if not self.is_processing:
            self.is_processing = True
            self.process_button.configure(text=self._s("cancel"))
            self.output_text.delete(1.0, tk.END)
            self.progress_var.set(0)
            threading.Thread(target=self.process_files, daemon=True).start()
        else:
            self.is_processing = False
            self.process_button.configure(text=self._s("process"))


# ─────────────────────────────────────────────────────────────────────────────
#  CLI fallback — for scripting/automation without the GUI
# ─────────────────────────────────────────────────────────────────────────────

def process_folder(folder_path):
    print(f"Processing files in: {folder_path}")

    ignore_files = [
        "video_wan2_2_5b_i2v",
        "depth_controlnet",
        "flux_redux_model_example",
        "image_qwen_image_union_control_lora",
        "image2image",
    ]

    for filename in os.listdir(folder_path):
        if not filename.endswith(".json"):
            continue

        base_name = os.path.splitext(filename)[0]
        if any(ignore in base_name.lower() for ignore in ignore_files):
            print(f"Skipping ignored file: {filename}")
            continue

        file_path = os.path.join(folder_path, filename)
        print(f"\nProcessing file: {filename}")

        try:
            with open(file_path, "r", encoding="utf-8") as fh:
                try:
                    json_data = json.load(fh)
                    print(f"Successfully loaded JSON from {filename}")
                except json.JSONDecodeError as exc:
                    print(f"Error parsing JSON in {filename}: {exc}")
                    continue

            loras = get_loras_from_json(json_data)

            if not loras:
                print(f"No LORAs found in {filename}, skipping...")
                continue

            print(f"Found LORAs in {filename}: {', '.join(loras)}")

            new_name, new_path = resolve_new_name(folder_path, filename, loras)

            if new_path != file_path:
                try:
                    os.rename(file_path, new_path)
                    print(f"Renamed: {filename} -> {new_name}")
                except OSError as exc:
                    print(f"Error renaming {filename}: {exc}")
            else:
                print(f"File {filename} already has the correct name")

        except Exception as exc:
            print(f"Unexpected error processing {filename}: {exc}")


# ─────────────────────────────────────────────────────────────────────────────
#  Unified entry point — GUI by default, CLI when --folder is given
# ─────────────────────────────────────────────────────────────────────────────

def main_gui():
    root = tk.Tk()
    app = WorkflowRenamerGUI(root)
    root.mainloop()


def main_cli():
    parser = argparse.ArgumentParser(
        description="Rename workflow JSON files based on contained LORAs"
    )
    parser.add_argument(
        "--folder", "-f",
        help="Folder path containing workflow JSON files",
    )
    args = parser.parse_args()
    folder = args.folder or _load_saved_folder()
    if not folder:
        parser.error("No folder specified and no saved folder found. Use --folder / -f.")
    process_folder(folder)


def main_entry():
    argv = sys.argv[1:]
    if len(argv) == 2 and argv[0] == "--extract-icons":
        _extract_icons(argv[1])
        return
    if argv:
        # Any other argument (e.g. --folder, -f) runs the scriptable CLI
        # fallback instead of opening the window.
        main_cli()
    else:
        main_gui()


if __name__ == "__main__":
    main_entry()
